#include "Zancle/HasBuiltin.hpp"


#if ZA_HAS_BUILTIN(__is_class)

    ////////////////////////////////////////////////////////////
    #define ZA_IS_CLASS(...) __is_class(__VA_ARGS__)

#else

////////////////////////////////////////////////////////////
// Headers
////////////////////////////////////////////////////////////
    #include <type_traits>


    ////////////////////////////////////////////////////////////
    #define ZA_IS_CLASS(...) ::std::is_class_v<__VA_ARGS__>

#endif


namespace za
{
////////////////////////////////////////////////////////////
template <typename T>
inline constexpr bool isClass = ZA_IS_CLASS(T);

} // namespace za
